pedagogical:
{
  "intencao_pedagogica": "Ao final deste curso, o estudante será capaz de aplicar com autonomia as práticas essenciais de controle de versão distribuído utilizando o Git, estruturando históricos de alterações consistentes, gerenciando ramificações de desenvolvimento e integrando modificações para viabilizar fluxos de trabalho modernos de engenharia de software.",
  "estilo_didatico": "Abordagem instrucional orientada à autoaprendizagem assíncrona, combinando microconteúdos teóricos com exercícios práticos orientados por comandos de terminal e cenários simulados de desenvolvimento individual.",
  "objetivos_aprendizagem": [
    "Compreender a arquitetura interna e o ciclo de vida dos arquivos no Git (working directory, staging area e repositório).",
    "Configurar o ambiente local do Git com identificadores de usuário e preferências essenciais.",
    "Inicializar novos repositórios locais e clonar repositórios existentes.",
    "Registrar alterações incrementais no código por meio de comandos de staging e commits semânticos.",
    "Inspecionar o histórico de versões e comparar diferenças entre commits utilizando logs e diffs.",
    "Criar, alternar e fundir branches para isolamento de funcionalidades e correções.",
    "Identificar e solucionar conflitos de integração (merge conflicts) em arquivos de código.",
    "Sincronizar alterações entre o repositório local e servidores remotos utilizando push, pull e fetch."
  ],
  "competencias_desenvolvidas": [
    "Gestão do ciclo de vida e histórico de código-fonte.",
    "Operação de versionamento via interface de linha de comando (CLI).",
    "Isolamento de funcionalidades mediante estratégias básicas de branching.",
    "Resolução técnica de conflitos de código em integrações.",
    "Autonomia na manutenção e integridade de repositórios distribuídos."
  ],
  "referencias": [
    {
      "title": "Pro Git Book (Edição em Português)",
      "href": "https://git-scm.com/book/pt-br/v2"
    },
    {
      "title": "Documentação Oficial de Referência do Git",
      "href": "https://git-scm.com/docs"
    },
    {
      "title": "Atlassian Git Tutorials: Conceitos e Fluxos de Trabalho",
      "href": "https://www.atlassian.com/br/git/tutorials"
    },
    {
      "title": "GitHub Docs: Primeiros passos no Git",
      "href": "https://docs.github.com/pt/get-started"
    }
  ]
}

missions:
{
  "missions": [
    {
      "title": "O Cristal da Memória: Forjando os Primeiros Commits",
      "description": "Nesta etapa inicial, você criará um novo repositório local para registrar seus primeiros artefatos de código de forma segura. Você praticará a adição de arquivos na área de preparação e congelará marcos de evolução criando commits com mensagens descritivas. Ao final, explorará o histórico para garantir que cada versão foi imortalizada com sucesso.",
      "rationale": "Estabelece a base conceitual e operacional do controle de versão local, permitindo ao estudante dominar o ciclo de vida das alterações antes de lidar com ramificações complexas.",
      "badge_title": "Guardião da Memória Temporal",
      "mapped_objectives": [
        "registrar alterações com commits"
      ],
      "tags": [
        "git",
        "commits",
        "repositório",
        "versionamento"
      ]
    },
    {
      "title": "A Convergência dos Mundos: O Ritual do Merge",
      "description": "Você criará uma linha temporal alternativa criando uma nova branch para desenvolver uma pequena funcionalidade isolada. Após registrar as mudanças de forma segura no ramo secundário, realizará a integração dessa linha de volta à ramificação principal. Por fim, validará o histórico unificado para assegurar que todo o progresso converge harmonicamente.",
      "rationale": "Expande o conhecimento linear para fluxos de trabalho não destrutivos e colaborativos, ensinando o estudante a isolar tarefas e integrá-las com integridade.",
      "badge_title": "Mestre da Convergência",
      "mapped_objectives": [
        "integrar branches com merge"
      ],
      "tags": [
        "git",
        "branches",
        "merge",
        "fluxo-guiado"
      ]
    }
  ]
}

